--- dist_rwlock_shared_release_inductive.rs	2026-08-21 10:43:41.666195285 +0000
+++ dist_rwlock_shared_release_inductive_verified.rs	2026-08-26 09:31:48.443397340 +0000
@@ -210,6 +210,112 @@
         }
         #[inductive(shared_release)]
         fn shared_release_inductive(pre: Self, post: Self, val: (int, T)) {
+            broadcast use group_multiset_axioms;
+            let r = val.0;
+            let pre_f = Self::filter_r(pre.shared_guard, r);
+            let post_f = Self::filter_r(post.shared_guard, r);
+            assert(pre.shared_guard.count(val) > 0);
+            assert(pre_f.count(val) == pre.shared_guard.count(val));
+            assert forall |x: (int, T)|
+                #[trigger] Multiset::singleton(val).count(x) <= pre_f.count(x)
+            by {
+                if x == val {
+                    axiom_multiset_singleton(val);
+                    assert(pre_f.count(x) > 0);
+                } else {
+                    axiom_multiset_singleton_different(val, x);
+                }
+            }
+            assert(Multiset::singleton(val).subset_of(pre_f));
+            axiom_len_sub(pre_f, Multiset::singleton(val));
+            assert forall |x: (int, T)|
+                #[trigger] post.shared_guard.count(x) ==
+                    pre.shared_guard.remove(val).count(x)
+            by {
+                axiom_multiset_sub(pre.shared_guard, Multiset::singleton(val), x);
+            }
+            assert forall |x: (int, T)|
+                #[trigger] post_f.count(x) ==
+                    pre_f.sub(Multiset::singleton(val)).count(x)
+            by {
+                axiom_filter_count(post.shared_guard, |y: (int, T)| y.0 == r, x);
+                axiom_filter_count(pre.shared_guard, |y: (int, T)| y.0 == r, x);
+                axiom_multiset_sub(pre_f, Multiset::singleton(val), x);
+                axiom_multiset_singleton(val);
+                axiom_multiset_singleton_different(val, x);
+                if x.0 == r {
+                    if x == val {
+                        assert(x.0 == r);
+                    } else {
+                        assert(Multiset::singleton(val).count(x) == 0);
+                    }
+                } else {
+                    assert(x.0 != r);
+                }
+            }
+            assert(post_f =~= pre_f.sub(Multiset::singleton(val)));
+            assert(post_f.len() == pre_f.len() - 1);
+            assert forall |q: int, x: (int, T)|
+                q != r implies #[trigger] Self::filter_r(post.shared_guard, q).count(x) ==
+                    Self::filter_r(pre.shared_guard, q).count(x)
+            by {
+                assert(q != r);
+                axiom_filter_count(post.shared_guard, |y: (int, T)| y.0 == q, x);
+                axiom_filter_count(pre.shared_guard, |y: (int, T)| y.0 == q, x);
+                if x == val {
+                    assert(x.0 == val.0);
+                    assert(val.0 == r);
+                    axiom_filter_count(pre.shared_guard, |y: (int, T)| y.0 == q, x);
+                    axiom_multiset_sub(pre.shared_guard, Multiset::singleton(val), x);
+                    axiom_multiset_singleton(val);
+                } else {
+                    axiom_multiset_sub(pre.shared_guard, Multiset::singleton(val), x);
+                    axiom_multiset_singleton_different(val, x);
+                }
+            }
+            assert forall |q: int| 0 <= q < pre.rc_width && q != r implies
+                Self::filter_r(post.shared_guard, q) =~= Self::filter_r(pre.shared_guard, q)
+            by {
+                assert forall |x: (int, T)| #[trigger]
+                    Self::filter_r(post.shared_guard, q).count(x) ==
+                    Self::filter_r(pre.shared_guard, q).count(x) by {
+                    assert(q != r);
+                };
+                axiom_multiset_ext_equal(Self::filter_r(post.shared_guard, q),
+                    Self::filter_r(pre.shared_guard, q));
+            }
+            assert(Self::filter_r(post.shared_guard, r).len() == post_f.len());
+            assert(Self::filter_r(pre.shared_guard, r).len() == pre_f.len());
+            assert forall |q: int| 0 <= q < pre.rc_width implies
+                Self::filter_r(post.shared_guard, q).len() ==
+                    if q == r { Self::filter_r(pre.shared_guard, q).len() - 1 }
+                    else { Self::filter_r(pre.shared_guard, q).len() as int }
+            by {
+                if q == r {
+                    assert(Self::filter_r(post.shared_guard, q).len() == post_f.len());
+                    assert(Self::filter_r(pre.shared_guard, q).len() == pre_f.len());
+                } else {
+                    assert(Self::filter_r(post.shared_guard, q) =~= Self::filter_r(pre.shared_guard, q));
+                    assert(Self::filter_r(post.shared_guard, q) == Self::filter_r(pre.shared_guard, q));
+                }
+            }
+            assert forall |q: int| 0 <= q < post.rc_width implies
+                post.ref_counts.index(q) ==
+                    post.shared_pending.count(q) as int +
+                    Self::filter_r(post.shared_guard, q).len() as int
+            by {
+                assert(0 <= q < pre.rc_width);
+                if q == r {
+                    assert(post.ref_counts.index(q) == pre.ref_counts.index(q) - 1);
+                    assert(post.shared_pending.count(q) == pre.shared_pending.count(q));
+                    assert(Self::filter_r(post.shared_guard, q).len() ==
+                        Self::filter_r(pre.shared_guard, q).len() - 1);
+                } else {
+                    assert(post.ref_counts.index(q) == pre.ref_counts.index(q));
+                    assert(post.shared_pending.count(q) == pre.shared_pending.count(q));
+                }
+                assert(pre.shared_counts_agree());
+            }
         }
     }
 }
